function r(id, name, url, category, type, description, nextAction, matchSites = [], difficulty = null, authoredTags = [], authoredPhrases = []) {
  const parsed = new URL(url);
  if (parsed.protocol !== 'https:') throw new TypeError(`Discovery URL must use HTTPS: ${id}`);
  const linkCheck = linkChecksById.get(id);
  const wasReachable = linkCheck?.url === url && linkCheck.status === 'ok';
  const site = parsed.hostname.toLowerCase().replace(/^www\./, '');
  const wordTokens = (`${id} ${site.split('.')[0]} ${category} ${type}`.toLowerCase().match(/[a-z0-9]+/g) ?? [])
    .filter((token) => token.length >= 2);
  const tags = [...new Set([...authoredTags, ...wordTokens])].slice(0, Math.max(3, authoredTags.length, wordTokens.length));
  const phrases = [...new Set([...authoredPhrases,
    name.toLowerCase(),
    id.replaceAll('-', ' '),
    `${name.toLowerCase()} ${type}`,
  ])];
  const level = difficulty ?? (advancedResources.has(id) ? 'advanced' : type === 'reference' ? 'intermediate' : 'beginner');
  return Object.freeze({
    id,
    name,
    url: parsed.href,
    site,
    category,
    type,
    description,
    nextAction,
    matchSites: Object.freeze([...new Set(matchSites.map((value) => value.toLowerCase()))]),
    tags: Object.freeze(tags),
    phrases: Object.freeze(phrases),
    difficulty: level,
    lastChecked: wasReachable ? linkCheck.checkedAt.slice(0, 10) : null,
    linkStatus: wasReachable ? 'ok' : 'unverified',
  });
}

export const discoveryCatalog = Object.freeze(rows);
